/* ============================================================
   Render
   ============================================================ */
const main = document.getElementById('main');

function cell(block, lang){
  const art = document.createElement('article');
  art.className = 'cell';
  art.lang = lang;
  let html = '';
  if (block.kicker){
    const k = typeof block.kicker === 'string' ? block.kicker : block.kicker[lang];
    if (k) html += '<span class="kicker">' + k + '</span>';
  }
  if (block.lead){
    html += '<p class="lead">' + block[lang] + '</p>';
  } else {
    html += block[lang];
  }
  art.innerHTML = html;
  if (block.callout) art.firstElementChild && art.classList.add('is-callout');
  return art;
}

function render(){
  const frag = document.createDocumentFragment();

  LEVELS.forEach(function(level){
    const sec = document.createElement('section');
    sec.className = 'level';
    sec.id = 'level-' + level.n;
    sec.dataset.level = String(level.n);

    const head = document.createElement('div');
    head.className = 'level-head';
    head.innerHTML =
      '<span class="badge" aria-hidden="true">' + level.n + '</span>' +
      '<div>' +
        '<h2 lang="en">' + level.en + '</h2>' +
        '<span class="zh-title" lang="zh">' + level.zh + '</span> ' +
        '<span class="sub">· ' + level.sub + '</span>' +
      '</div>';
    sec.appendChild(head);

    const pairs = document.createElement('div');
    pairs.className = 'pairs';
    level.blocks.forEach(function(block){
      const row = document.createElement('div');
      row.className = 'pair';
      row.appendChild(cell(block, 'en'));
      row.appendChild(cell(block, 'zh'));
      pairs.appendChild(row);
    });
    sec.appendChild(pairs);
    frag.appendChild(sec);
  });

  main.appendChild(frag);
}
render();

/* ============================================================
   Reveal on scroll
   ============================================================ */
const pairs = Array.prototype.slice.call(document.querySelectorAll('.pair'));
if ('IntersectionObserver' in window && !matchMedia('(prefers-reduced-motion: reduce)').matches){
  const io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); }
    });
  }, { rootMargin:'0px 0px -10% 0px', threshold:0.05 });
  pairs.forEach(function(p){ io.observe(p); });
} else {
  pairs.forEach(function(p){ p.classList.add('in'); });
}

/* ============================================================
   Controls: level filter + language view
   ============================================================ */
const body = document.body;

function setPressed(group, attr, value){
  document.querySelectorAll('.seg button[' + attr + ']').forEach(function(b){
    b.setAttribute('aria-pressed', b.dataset[attr] === value ? 'true' : 'false');
  });
}

function showLevel(n){
  body.dataset.level = n;
  document.querySelectorAll('.level').forEach(function(sec){
    sec.hidden = (n !== 'all' && sec.dataset.level !== n);
  });
  setPressed('level', 'level', n);
}

function showView(v){
  body.dataset.view = v;
  setPressed('view', 'view', v);
  document.documentElement.lang = (v === 'zh') ? 'zh-CN' : (v === 'en' ? 'en' : 'en');
}

document.querySelectorAll('.seg button[data-level]').forEach(function(b){
  b.addEventListener('click', function(){
    showLevel(b.dataset.level);
    const target = b.dataset.level === 'all'
      ? document.getElementById('main')
      : document.getElementById('level-' + b.dataset.level);
    if (target) target.scrollIntoView({ behavior:'smooth', block:'start' });
  });
});

document.querySelectorAll('.seg button[data-view]').forEach(function(b){
  b.addEventListener('click', function(){ showView(b.dataset.view); });
});

document.getElementById('top-btn').addEventListener('click', function(){
  window.scrollTo({ top:0, behavior:'smooth' });
});

/* Progress bar */
const bar = document.getElementById('progress');
function tick(){
  const h = document.documentElement.scrollHeight - window.innerHeight;
  bar.style.width = (h > 0 ? Math.min(1, window.scrollY / h) * 100 : 0) + '%';
}
addEventListener('scroll', tick, { passive:true });
addEventListener('resize', tick);
tick();

/* Keyboard shortcuts */
addEventListener('keydown', function(e){
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const t = e.target;
  if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;

  const secs = Array.prototype.slice.call(document.querySelectorAll('.level:not([hidden])'));
  const k = e.key.toLowerCase();

  if (['1','2','3'].indexOf(k) > -1){ showLevel(k); document.getElementById('level-' + k).scrollIntoView({behavior:'smooth',block:'start'}); e.preventDefault(); }
  else if (k === '0'){ showLevel('all'); window.scrollTo({top:0,behavior:'smooth'}); e.preventDefault(); }
  else if (k === 'l'){
    const order = ['both','en','zh'];
    showView(order[(order.indexOf(body.dataset.view) + 1) % order.length]);
    e.preventDefault();
  }
  else if (k === 'j' || k === 'k'){
    if (!secs.length) return;
    const mid = window.scrollY + window.innerHeight * 0.35;
    let idx = secs.findIndex(function(s){ return s.offsetTop >= mid - 4; });
    if (idx === -1) idx = secs.length - 1;
    if (k === 'j') idx = Math.min(secs.length - 1, idx + (secs[idx] && secs[idx].offsetTop <= mid ? 1 : 0));
    else idx = Math.max(0, idx - 1);
    secs[idx].scrollIntoView({ behavior:'smooth', block:'start' });
    e.preventDefault();
  }
});
</script>
</body>
