{"content": "<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>طبقات الأرض البنيوية — من القشرة إلى اللب</title>
<meta name="description" content="عرض تعليمي مبسّط عن طبقات الأرض: القشرة والوشاح واللب الخارجي واللب الداخلي، مع رسوم توضيحية وبيانات.">
<meta name="author" content="Jennifer Robins">
<style>
  /* ============ الرموز التصميمية / Design tokens ============ */
  :root{
    --crust:#8d6e53;   --crust-2:#a8886a;
    --mantle:#c0562b;  --mantle-2:#d9764a;
    --outer:#e8912a;   --outer-2:#f5ac4e;
    --inner:#f5d76e;   --inner-2:#ffe9a3;
    --ocean:#2b6a8f;

    --ink:#1a2230; --ink-soft:#4c5a70; --paper:#ffffff; --bg:#f5f7fa;
    --rule:#dde4ec; --accent:#1f6f8b; --space:#0b1622;
    --radius:16px; --gap:clamp(14px,2.4vw,28px); --maxw:1080px;

    --ar:"Noto Kufi Arabic","Noto Naskh Arabic","Geeza Pro","Al Bayan","Damascus",
         "Segoe UI",Tahoma,"Times New Roman",Arial,sans-serif;
    --mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  }
  @media (prefers-color-scheme:dark){
    :root{
      --ink:#e8eef6; --ink-soft:#a5b4c8; --paper:#121c28; --bg:#080f18;
      --rule:#233044; --accent:#5fb6d4; --space:#060d16;
    }
  }

  *,*::before,*::after{box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    margin:0; background:var(--bg); color:var(--ink);
    font-family:var(--ar); font-size:17px; line-height:1.95;
    -webkit-font-smoothing:antialiased; text-rendering:optimizeLegibility;
  }
  h1,h2,h3{line-height:1.5; margin:0; font-weight:700}
  p{margin:0 0 .85em}
  :is(h1,h2,h3,p,li,td,th) code{font-family:var(--mono);font-size:.86em}

  /* أرقام ووحدات: عُزلة ثنائية الاتجاه حتى لا تنقلب النطاقات مثل 5–10 */
  .n{direction:ltr; unicode-bidi:isolate; white-space:nowrap; font-variant-numeric:tabular-nums}

  .wrap{max-width:var(--maxw); margin-inline:auto; padding-inline:var(--gap)}

  /* ============ الترويسة ============ */
  header.hero{
    background:
      radial-gradient(1200px 520px at 80% -10%, color-mix(in srgb,var(--accent) 30%,transparent), transparent 70%),
      linear-gradient(180deg, var(--space), #14283f 65%, var(--bg));
    color:#eef4fb; padding-block:clamp(28px,6vw,64px) clamp(20px,4vw,40px);
    border-bottom:1px solid var(--rule);
  }
  @supports not (background:color-mix(in srgb,red,blue)){header.hero{background:var(--space);color:#eef4fb}}
  header.hero .kicker{
    display:inline-block; font-size:.74rem; letter-spacing:.18em; text-transform:uppercase;
    color:var(--inner-2); border:1px solid color-mix(in srgb,var(--inner) 55%,transparent);
    border-radius:999px; padding:4px 12px; margin-bottom:14px;
  }
  header.hero h1{font-size:clamp(1.7rem,4.6vw,2.7rem); letter-spacing:-.01em}
  header.hero .sub{max-width:62ch; color:#c3d3e4; margin-top:.6em; font-size:1.02rem}

  /* شريط حقائق */
  .facts{display:flex; flex-wrap:wrap; gap:10px; margin-top:22px}
  .facts div{
    background:rgba(255,255,255,.07); border:1px solid rgba(255,255,255,.14);
    border-radius:12px; padding:8px 14px; min-width:150px;
  }
  .facts b{display:block; font-size:1.12rem; color:#fff}
  .facts span{font-size:.76rem; color:#b9c9db}

  /* ============ الأقسام ============ */
  main{padding-block:clamp(24px,4vw,44px)}
  section{margin-bottom:clamp(30px,5vw,56px)}
  .sec-head{display:flex; align-items:baseline; gap:12px; flex-wrap:wrap; margin-bottom:16px}
  .sec-head h2{font-size:clamp(1.15rem,2.6vw,1.5rem)}
  .sec-head .num{
    flex:0 0 auto; width:30px; height:30px; border-radius:50%; display:grid; place-items:center;
    background:var(--accent); color:#fff; font-size:.85rem; font-weight:700;
  }
  @media (prefers-color-scheme:dark){.sec-head .num{color:#06121c}}
  .sec-head p{margin:0; color:var(--ink-soft); font-size:.92rem}

  .panel{
    background:var(--paper); border:1px solid var(--rule); border-radius:var(--radius);
    padding:clamp(16px,2.6vw,26px);
  }

  /* ============ الرسم المقطعي ============ */
  .cutaway{display:grid; grid-template-columns:minmax(240px,1fr) minmax(220px,320px); gap:clamp(14px,2.4vw,26px); align-items:center}
  @media (max-width:760px){.cutaway{grid-template-columns:1fr}}
  svg{display:block; width:100%; height:auto}
  .diagram{background:radial-gradient(circle at 50% 45%, #12283f, var(--space) 72%); border-radius:var(--radius); padding:10px}
  .diagram text{font-family:var(--ar); fill:#e9f1fa; font-size:15px; font-weight:600}
  .diagram text.small{font-size:11.5px; font-weight:400; fill:#a9c0d4}
  .diagram .lead{stroke:#cfe0f0; stroke-width:1.1; fill:none; opacity:.85}
  .diagram .dot{fill:#fff}
  .layer{cursor:pointer; transition:opacity .22s, transform .22s}
  .layer:focus{outline:none}
  .layer:focus-visible .ring{stroke:#fff; stroke-width:2.4}
  svg[data-active] .layer:not(.active){opacity:.28}
  .layer.active .ring{stroke:#fff; stroke-width:2.2}

  /* أزرار الطبقات */
  .chips{display:flex; flex-wrap:wrap; gap:8px; margin-bottom:14px}
  .chip{
    font-family:inherit; font-size:.85rem; font-weight:600; color:var(--ink);
    background:var(--paper); border:1px solid var(--rule); border-radius:999px;
    padding:7px 14px 7px 12px; cursor:pointer; display:inline-flex; align-items:center; gap:8px;
    transition:border-color .15s, background .15s, transform .12s;
  }
  .chip:hover{border-color:var(--accent); transform:translateY(-1px)}
  .chip .sw{width:12px; height:12px; border-radius:3px; flex:0 0 auto; box-shadow:inset 0 0 0 1px rgba(0,0,0,.25)}
  .chip[aria-pressed="true"]{background:var(--accent); color:#fff; border-color:var(--accent)}
  @media (prefers-color-scheme:dark){.chip[aria-pressed="true"]{color:#06121c}}
  .chip.ghost{color:var(--ink-soft)}

  /* ============ بطاقات الطبقات ============ */
  .cards{display:grid; gap:14px; grid-template-columns:repeat(auto-fit,minmax(250px,1fr))}
  .card{
    background:var(--paper); border:1px solid var(--rule); border-radius:var(--radius);
    padding:18px; border-inline-start:6px solid var(--c,var(--accent));
    transition:box-shadow .2s, border-color .2s, opacity .2s;
  }
  .card.active{box-shadow:0 0 0 2px var(--c), 0 10px 26px -14px rgba(0,0,0,.45)}
  body.has-sel .card:not(.active){opacity:.55}
  .card h3{font-size:1.06rem; display:flex; align-items:center; gap:8px; margin-bottom:2px}
  .card h3 .sw{width:14px; height:14px; border-radius:4px; background:var(--c)}
  .card .en{font-size:.72rem; letter-spacing:.1em; color:var(--ink-soft); font-family:system-ui,sans-serif; direction:ltr; text-align:start}
  .card dl{margin:.6em 0 0; display:grid; grid-template-columns:auto 1fr; gap:4px 10px; font-size:.9rem}
  .card dt{color:var(--ink-soft); white-space:nowrap}
  .card dd{margin:0}
  .card .note{
    margin-top:12px; padding:9px 12px; font-size:.85rem; border-radius:10px;
    background:color-mix(in srgb,var(--c) 12%,var(--paper)); border:1px solid color-mix(in srgb,var(--c) 30%,transparent);
  }
  @supports not (background:color-mix(in srgb,red,blue)){.card .note{background:var(--bg)}}
  .card .note b{color:var(--c)}

  /* ============ رسم الحرارة ============ */
  .chart-wrap{display:grid; grid-template-columns:1fr; gap:10px}
  .chart svg{direction:ltr}
  .chart .grid{stroke:var(--rule); stroke-width:1}
  .chart .axis{stroke:var(--ink-soft); stroke-width:1.2}
  .chart text{font-family:var(--ar); fill:var(--ink-soft); font-size:11.5px}
  .chart .tick{font-family:system-ui,var(--ar); font-size:11px}
  .chart .curve{fill:none; stroke:#d1495b; stroke-width:2.6; stroke-linejoin:round; stroke-linecap:round}
  .chart .bandlabel{font-size:11.5px; fill:var(--ink)}

  /* ============ أشرطة النسب ============ */
  .bars{display:grid; gap:12px}
  .bar-row{display:grid; grid-template-columns:110px 1fr auto; gap:12px; align-items:center; font-size:.9rem}
  @media (max-width:520px){.bar-row{grid-template-columns:84px 1fr auto}}
  .bar-track{background:var(--bg); border:1px solid var(--rule); border-radius:999px; height:18px; overflow:hidden}
  .bar-fill{height:100%; border-radius:999px; background:linear-gradient(90deg,var(--c),color-mix(in srgb,var(--c) 65%,#fff))}
  @supports not (background:linear-gradient(90deg,red,blue)){.bar-fill{background:var(--c)}}
  .bar-val{font-size:.82rem; color:var(--ink-soft)}
  .analogy{
    margin-top:16px; padding:14px 16px; border-radius:12px; font-size:.95rem;
    background:color-mix(in srgb,var(--mantle) 10%,var(--paper));
    border:1px dashed color-mix(in srgb,var(--mantle) 45%,transparent);
  }
  @supports not (background:color-mix(in srgb,red,blue)){.analogy{background:var(--bg)}}

  /* ============ الزلازل ============ */
  .two-col{display:grid; grid-template-columns:1.05fr .95fr; gap:16px}
  @media (max-width:820px){.two-col{grid-template-columns:1fr}}
  ul.clean{list-style:none; padding:0; margin:0; display:grid; gap:10px}
  ul.clean li{display:grid; grid-template-columns:auto 1fr; gap:10px; align-items:start}
  ul.clean li .ico{
    width:24px; height:24px; border-radius:7px; display:grid; place-items:center; font-size:.78rem; font-weight:700;
    background:color-mix(in srgb,var(--accent) 16%,var(--paper)); color:var(--accent);
    border:1px solid color-mix(in srgb,var(--accent) 32%,transparent);
  }
  @supports not (background:color-mix(in srgb,red,blue)){ul.clean li .ico{background:var(--bg); color:var(--ink)}}
  .disc{display:grid; gap:0; border:1px solid var(--rule); border-radius:12px; overflow:hidden}
  .disc div{display:grid; grid-template-columns:auto 1fr auto; gap:10px; padding:10px 14px; font-size:.9rem; align-items:center}
  .disc div + div{border-top:1px solid var(--rule)}
  .disc .km{color:var(--ink-soft); font-size:.84rem}
  .disc .pin{width:9px; height:9px; border-radius:50%; background:var(--c,var(--accent))}

  /* ============ الجدول ============ */
  .table-wrap{overflow-x:auto; border:1px solid var(--rule); border-radius:var(--radius); background:var(--paper)}
  table{border-collapse:collapse; width:100%; font-size:.9rem; min-width:680px}
  caption{text-align:start; padding:14px 16px 0; font-weight:700}
  th,td{padding:11px 14px; text-align:start; border-bottom:1px solid var(--rule); vertical-align:top}
  thead th{
    background:color-mix(in srgb,var(--accent) 8%,var(--paper)); font-size:.8rem;
    letter-spacing:.04em; color:var(--ink-soft); position:sticky; top:0;
  }
  @supports not (background:color-mix(in srgb,red,blue)){thead th{background:var(--bg)}}
  tbody tr:last-child td{border-bottom:0}
  tbody tr:hover td{background:color-mix(in srgb,var(--accent) 5%,transparent)}
  td .sw{display:inline-block; width:10px; height:10px; border-radius:3px; background:var(--c); margin-inline-end:6px}

  /* ============ التذييل ============ */
  footer{border-top:1px solid var(--rule); margin-top:20px; padding-block:22px 40px; font-size:.82rem; color:var(--ink-soft)}
  footer .cr{display:flex; flex-wrap:wrap; gap:.3em .8em; align-items:baseline; margin-top:10px; padding-top:12px; border-top:1px solid var(--rule)}
  footer .cr .name{font-weight:700; color:var(--ink)}

  /* ============ الحركة ============ */
  .reveal{opacity:0; transform:translateY(12px)}
  .reveal.in{opacity:1; transform:none; transition:opacity .5s ease, transform .5s ease}
  @media (prefers-reduced-motion:reduce){
    html{scroll-behavior:auto}
    .reveal,.reveal.in{opacity:1; transform:none; transition:none}
  }

  /* ============ الطباعة ============ */
  @media print{
    body{background:#fff; color:#000; font-size:11pt}
    header.hero{background:#fff!important; color:#000; border-bottom:2px solid #000}
    header.hero .sub,.facts span{color:#333}
    .facts div{background:#f2f2f2; border-color:#bbb}
    .facts b{color:#000}
    .diagram{background:#fff; border:1px solid #999}
    .diagram text{fill:#000} .diagram text.small{fill:#444}
    .diagram .lead{stroke:#333} .chip{display:none}
    .card,.panel{break-inside:avoid; page-break-inside:avoid}
    .reveal{opacity:1!important; transform:none!important}
  }
</style>
</head>
<body>

<header class="hero">
  <div class="wrap">
    <span class="kicker">علوم الأرض · بنية الكوكب</span>
    <h1>طبقات الأرض البنيوية</h1>
    <p class="sub">
      من القشرة الرقيقة إلى اللب الحديدي الصلب: رحلة رأسية بعمق <span class="n">6371</span> كيلومترًا
      عبر أربع طبقات مختلفة التركيب والحالة والحرارة.
    </p>
    <div class="facts">
      <div><b><span class="n">6371</span> كم</b> <span>نصف القطر المتوسط</span></div>
      <div><b><span class="n">5.51</span> غم/سم³</b> <span>الكثافة المتوسطة</span></div>
      <div><b><span class="n">4.54</span> مليار سنة</b> <span>عمر الأرض</span></div>
      <div><b><span class="n">~5400 °م</span></b> <span>حرارة المركز</span></div>
      <div><b><span class="n">0.2%</span></b> <span>أعمق حفرة بشريّة من نصف القطر</span></div>
    </div>
  </div>
</header>

<main>
  <div class="wrap">

    <!-- ============ 1. المقطع الرأسي ============ -->
    <section id="cutaway" class="reveal">
      <div class="sec-head">
        <span class="num">١</span>
        <h2>مقطعٌ رأسيّ في جسم الأرض</h2>
        <p>اضغط على أي طبقة في الرسم أو على الأزرار لعزلها.</p>
      </div>

      <div class="panel">
        <div class="chips" role="group" aria-label="اختيار طبقة">
          <button type="button" class="chip" data-layer="crust"  aria-pressed="false"><span class="sw" style="background:var(--crust)"></span>القشرة</button>
          <button type="button" class="chip" data-layer="mantle" aria-pressed="false"><span class="sw" style="background:var(--mantle)"></span>الوشاح</button>
          <button type="button" class="chip" data-layer="outer"  aria-pressed="false"><span class="sw" style="background:var(--outer)"></span>اللب الخارجي</button>
          <button type="button" class="chip" data-layer="inner"  aria-pressed="false"><span class="sw" style="background:var(--inner)"></span>اللب الداخلي</button>
          <button type="button" class="chip ghost" id="reset" aria-pressed="false">إظهار الكل ✕</button>
        </div>

        <div class="cutaway">
          <figure class="diagram" style="margin:0">
            <svg viewBox="0 0 560 420" role="img" aria-labelledby="cut-title cut-desc">
              <title id="cut-title">مقطعٌ في الكرة الأرضية يُظهر الطبقات الأربع</title>
              <desc id="cut-desc">
                دائرة تمثّل الأرض مع قطاع مكشوف من ربعها يُظهر من الخارج إلى الداخل:
                القشرة الرقيقة، ثم الوشاح، ثم اللب الخارجي السائل، ثم اللب الداخلي الصلب.
              </desc>

              <defs>
                <clipPath id="wedge">
                  <path d="M350,210 L280.3,359.5 A165,165 0 0 1 280.3,60.5 Z"/>
                </clipPath>
                <radialGradient id="atmo" cx="50%" cy="50%" r="50%">
                  <stop offset="88%" stop-color="#7fb2e0" stop-opacity="0"/>
                  <stop offset="100%" stop-color="#7fb2e0" stop-opacity=".45"/>
                </radialGradient>
              </defs>

              <!-- الغلاف الجوي -->
              <circle cx="350" cy="210" r="176" fill="url(#atmo)"/>
              <!-- سطح الأرض (الجزء غير المقطوع) -->
              <circle cx="350" cy="210" r="165" fill="var(--ocean)"/>
              <circle cx="350" cy="210" r="165" fill="none" stroke="#9ec7e0" stroke-width="1" opacity=".6"/>

              <!-- القطاع المكشوف: طبقات متحدة المركز -->
              <g clip-path="url(#wedge)">
                <g class="layer" data-layer="crust" tabindex="0" role="button" aria-label="القشرة">
                  <circle class="ring" cx="350" cy="210" r="165" fill="var(--crust)"/>
                </g>
                <g class="layer" data-layer="mantle" tabindex="0" role="button" aria-label="الوشاح">
                  <circle class="ring" cx="350" cy="210" r="160.5" fill="var(--mantle)"/>
                  <circle cx="350" cy="210" r="160.5" fill="none" stroke="#000" stroke-opacity=".25"/>
                </g>
                <g class="layer" data-layer="outer" tabindex="0" role="button" aria-label="اللب الخارجي">
                  <circle class="ring" cx="350" cy="210" r="75" fill="var(--outer)"/>
                  <circle cx="350" cy="210" r="75" fill="none" stroke="#000" stroke-opacity=".3"/>
                </g>
                <g class="layer" data-layer="inner" tabindex="0" role="button" aria-label="اللب الداخلي">
                  <circle class="ring" cx="350" cy="210" r="31.6" fill="var(--outer-2)"/>
                  <circle class="ring" cx="350" cy="210" r="9.2" fill="var(--inner)"/>
                  <circle cx="350" cy="210" r="9.2" fill="none" stroke="#000" stroke-opacity=".3"/>
                </g>
              </g>

              <!-- حدود بخطوط فاصلة -->
              <path d="M350,210 L280.3,359.5" stroke="#fff" stroke-opacity=".55" stroke-width="1.4"/>
              <path d="M350,210 L280.3,60.5"  stroke="#fff" stroke-opacity=".55" stroke-width="1.4"/>

              <!-- خطوط التوصيل والتسميات -->
              <g>
                <polyline class="lead" points="236.9,323.1 219.9,340.1"/>
                <circle class="dot" cx="236.9" cy="323.1" r="2.6"/>
                <text x="214" y="345" text-anchor="end">القشرة</text>
                <text class="small" x="214" y="362" text-anchor="end">0 – 35 كم · صلبة</text>

                <polyline class="lead" points="239.1,250.4 177.1,272.9"/>
                <circle class="dot" cx="239.1" cy="250.4" r="2.6"/>
                <text x="171" y="277" text-anchor="end">الوشاح</text>
                <text class="small" x="171" y="294" text-anchor="end">35 – 2891 كم · صلب لزج</text>

