{"path": "/home/agent/workspace/movegen.py", "content": """"Move generation and perft for a small hobby chess engine.

Pure standard library, no external engines.

Scope of this pass (pseudo-legal moves only):
  * normal piece movement, including captures
  * pawn single and double pushes
Not handled yet (intentionally):
  * castling
  * en passant
  * promotion (a pawn reaching the last rank is emitted as a plain move,
    e.g. 'a7a8', with no promotion suffix)
  * check / pin legality -- moves that leave the side to move's king in
    check are still returned

Board representation is 0x88: a 128 element list where a square is
``rank * 16 + file`` with rank 0 == rank 1 and file 0 == 'a'.  A target
square is off the board iff ``sq & 0x88`` is non-zero.

Pieces are small signed integers: white positive, black negative,
P/N/B/R/Q/K == 1/2/3/4/5/6, 0 == empty.
"""

from __future__ import annotations

__all__ = ["legal_moves", "perft"]

# ---------------------------------------------------------------------------
# Piece constants
# ---------------------------------------------------------------------------

PAWN, KNIGHT, BISHOP, ROOK, QUEEN, KING = 1, 2, 3, 4, 5, 6
_EMPTY = 0

_FEN_TO_PIECE = {
    "P": PAWN, "N": KNIGHT, "B": BISHOP, "R": ROOK, "Q": QUEEN, "K": KING,
    "p": -PAWN, "n": -KNIGHT, "b": -BISHOP, "r": -ROOK, "q": -QUEEN, "k": -KING,
}

# Jump pieces (single step, no sliding).
_KNIGHT_STEPS = (17, 15, 18, 14, -17, -15, -18, -14)
_KING_STEPS = (17, 16, 15, 1, -17, -16, -15, -1)

# Slider step lists; a slider repeats its step until it leaves the board
# or hits a piece.
_SLIDE_DIRS = {
    BISHOP: (17, 15, -17, -15),
    ROOK: (16, 1, -16, -1),
    QUEEN: (17, 16, 15, 1, -17, -16, -15, -1),
}

# Pawn parameters keyed by side to move: (piece, one step, two steps, captures,
# home rank index).
_PAWN_PARAMS = {
    True: (PAWN, 16, 32, (15, 17), 1),      # white
    False: (-PAWN, -16, -32, (-15, -17), 6),  # black
}


# ---------------------------------------------------------------------------
# FEN handling
# ---------------------------------------------------------------------------

def _square_name(sq: int) -> str:
    """0x88 square index -> UCI square name, e.g. 27 -> 'e2'."""
    return chr(ord("a") + (sq & 7)) + chr(ord("1") + (sq >> 4))


def _square_index(name: str) -> int:
    """UCI square name -> 0x88 square index."""
    if len(name) != 2 or not ("a" <= name[0] <= "h") or not ("1" <= name[1] <= "8"):
        raise ValueError(f"invalid square: {name!r}")
    return (ord(name[1]) - ord("1")) * 16 + (ord(name[0]) - ord("a"))


def _parse_fen(fen: str) -> tuple[list[int], bool]:
    """Parse a FEN string.

    Returns ``(board, white_to_move)`` where ``board`` is a 128 element
    0x88 board.  Only the piece placement and side to move fields are used;
    the remaining fields are validated for shape so that malformed input is
    reported early rather than silently ignored.
    """
    if not isinstance(fen, str):
        raise ValueError("FEN must be a string")

    fields = fen.split()
    if len(fields) < 4:
        raise ValueError(f"FEN must have at least 4 fields, got {len(fields)}: {fen!r}")

    placement, side, castling, en_passant = fields[0], fields[1], fields[2], fields[3]

    rows = placement.split("/")
    if len(rows) != 8:
        raise ValueError(f"FEN board must have 8 ranks, got {len(rows)}: {placement!r}")

    board = [_EMPTY] * 128
    for row_index, row in enumerate(rows):
        rank = 7 - row_index                      # FEN starts at rank 8
        file_ = 0
        for char in row:
            if char.isdigit():
                advance = int(char)
                if advance == 0 or file_ + advance > 8:
                    raise ValueError(f"bad rank count in {row!r}")
                file_ += advance
            else:
                piece = _FEN_TO_PIECE.get(char)
                if piece is None:
                    raise ValueError(f"unknown piece character {char!r} in {placement!r}")
                if file_ >= 8:
                    raise ValueError(f"bad rank count in {row!r}")
                board[rank * 16 + file_] = piece
                file_ += 1
        if file_ != 8:
            raise ValueError(f"rank {row!r} has {file_} squares, expected 8")

    if side not in ("w", "b"):
        raise ValueError(f"side to move must be 'w' or 'b', got {side!r}")
    if any(c not in "KQkq" for c in castling):
        raise ValueError(f"invalid castling field {castling!r}")
    if en_passant != "-":
        _square_index(en_passant)                 # validates shape only
    for extra in fields[4:]:
        if not extra.isdigit():
            raise ValueError(f"invalid counter field {extra!r}")

    return board, side == "w"


# ---------------------------------------------------------------------------
# Move generation
# ---------------------------------------------------------------------------

def _gen_moves(board: list[int], white: bool) -> list[tuple[int, int]]:
    """All pseudo-legal moves for the side to move as (from, to) index pairs."""
    moves: list[tuple[int, int]] = []
    append = moves.append
    own_side = white

    if white:
        pawn, step, dbl_step, captures, home_rank = _PAWN_PARAMS[True]
    else:
        pawn, step, dbl_step, captures, home_rank = _PAWN_PARAMS[False]

    for sq in range(128):
        if sq & 0x88:
            continue
        piece = board[sq]
        if piece == _EMPTY or (piece > 0) is not own_side:
            continue

        piece_type = piece if piece > 0 else -piece

        if piece_type == PAWN:
            to = sq + step
            if not (to & 0x88) and board[to] == _EMPTY:
                append((sq, to))
                to_double = sq + dbl_step
                if (
                    (sq >> 4) == home_rank
                    and not (to_double & 0x88)
                    and board[to_double] == _EMPTY
                ):
                    append((sq, to_double))
            for delta in captures:
                to = sq + delta
                if to & 0x88:
                    continue
                target = board[to]
                if target != _EMPTY and (target > 0) is not own_side:
                    append((sq, to))
            continue

        if piece_type == KNIGHT:
            for delta in _KNIGHT_STEPS:
                to = sq + delta
                if to & 0x88:
                    continue
                target = board[to]
                if target == _EMPTY or (target > 0) is not own_side:
                    append((sq, to))
            continue

        if piece_type == KING:
            for delta in _KING_STEPS:
                to = sq + delta
                if to & 0x88:
                    continue
                target = board[to]
                if target == _EMPTY or (target > 0) is not own_side:
                    append((sq, to))
            continue

        for delta in _SLIDE_DIRS[piece_type]:
            to = sq + delta
            while not (to & 0x88):
                target = board[to]
                if target == _EMPTY:
                    append((sq, to))
                else:
                    if (target > 0) is not own_side:
                        append((sq, to))
                    break
                to += delta

    return moves


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def legal_moves(fen: str) -> list[str]:
    """Every move available to the side to move, in UCI notation.

    Pseudo-legal in this pass: castling, en passant, promotion suffixes and
    check/pin legality are not considered yet.
    """
    board, white = _parse_fen(fen)
    return [f"{_square_name(src)}{_square_name(dst)}"
            for src, dst in _gen_moves(board, white)]


def perft(fen: str, depth: int) -> int:
    """Count leaf nodes reachable from ``fen`` at ``depth``.

    ``perft(fen, 0)`` is 1.  Uses the same pseudo-legal move generator as
    :func:`legal_moves`.
    """
    if not isinstance(depth, int) or isinstance(depth, bool):
        raise TypeError(f"depth must be an int, got {depth!r}")
    if depth < 0:
        raise ValueError(f"depth must be non-negative, got {depth}")

    board, white = _parse_fen(fen)
    return _perft(board, white, depth)


def _perft(board: list[int], white: bool, depth: int) -> int:
    if depth == 0:
        return 1

    moves = _gen_moves(board, white)
    if depth == 1:
        return len(moves)

    nodes = 0
    for src, dst in moves:
        captured = board[dst]
        piece = board[src]
        board[src] = _EMPTY
        board[dst] = piece
        nodes += _perft(board, not white, depth - 1)
        board[src] = piece
        board[dst] = captured
    return nodes


if __name__ == "__main__":  # pragma: no cover - convenience only
    start = "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1"
    print(" ".join(legal_moves(start)))
    for d in range(5):
        print(f"perft({d}) = {perft(start, d)}")
"}

